package staticpod

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"text/template"
)

// ManifestFileName is the name a VM's rendered manifest is written under,
// within its StaticPodPath.
func ManifestFileName(name string) string {
	return "kontur-vm-" + name + ".yaml"
}

// PodName is the Kubernetes pod name a VM's manifest declares.
func PodName(name string) string {
	return "kontur-vm-" + name
}

// Render produces the static pod manifest YAML for spec: one pod with a
// netshim init container (splicing this VM's tap device onto the pod's
// own interface, plus the control link) and a single VM container, both
// running the same kontur image in its two modes ("netshim" and "run").
// It follows the same shape as
// deploy/static-kubelet/manifests/kontur-static-pod.yaml, generated instead
// of hand-written so it can be regenerated on every "konturctl vm update".
func Render(s VMSpec) (string, error) {
	var buf bytes.Buffer
	if err := manifestTemplate.Execute(&buf, s); err != nil {
		return "", fmt.Errorf("rendering manifest for %q: %w", s.Name, err)
	}
	return buf.String(), nil
}

var manifestTemplate = template.Must(template.New("manifest").Funcs(template.FuncMap{
	"yq":      yamlQuote,
	"itoa":    strconv.Itoa,
	"PodName": PodName,
	"fmtBool": strconv.FormatBool,
}).Parse(netshimEnvTemplateSrc + manifestTemplateSrc))

// yamlQuote renders s as a double-quoted YAML scalar, escaping backslashes
// and double quotes so arbitrary values (paths, cmdlines, image refs) are
// always safe to interpolate regardless of what characters they contain.
func yamlQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\', '"':
			b.WriteByte('\\')
			b.WriteRune(r)
		case '\n':
			b.WriteString(`\n`)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// netshimEnvTemplateSrc is the block of networking settings netshim
// reads, shared by the init container and the VM container -- which
// derives its own --net from the same values -- so the two can never
// disagree.
const netshimEnvTemplateSrc = `{{define "netshimEnv"}}
        - name: NETSHIM_VM
          value: {{yq .Name}}
        - name: NETSHIM_BRIDGE
          value: {{yq .Bridge}}
        - name: NETSHIM_CONTROL_CIDR
          value: {{yq .ControlCIDR}}
        - name: NETSHIM_EXTERNAL_IFACE
          value: {{yq .ExternalIface}}
        - name: NETSHIM_DNS
          value: {{yq .DNS}}
{{- end}}`

const manifestTemplateSrc = `# Generated by "konturctl vm" -- do not edit by hand, "konturctl vm update"
# will overwrite this file and "konturctl vm delete" removes it. Managed VM: {{.Name}}
apiVersion: v1
kind: Pod
metadata:
  name: {{yq (PodName .Name)}}
  labels:
    app: kontur-vm
    kontur.dev/vm: {{yq .Name}}
spec:
  restartPolicy: Always
  terminationGracePeriodSeconds: {{itoa .TerminationGracePeriodSeconds}}
  initContainers:
    - name: netshim
      image: {{yq .KonturImage}}
      args: ["netshim"]
      env:
{{- template "netshimEnv" .}}
      securityContext:
        # netshim writes no sysctl and installs no nftables rules, so
        # under docker it runs with CAP_NET_ADMIN and an explicitly
        # granted /dev/net/tun instead (see internal/dockervm). A pod has
        # no per-device grant to give it, and the netlink library creates
        # a tap by opening that device, so here it stays privileged.
        privileged: true
  containers:
    - name: {{yq .Name}}
      image: {{yq .KonturImage}}
      args: ["run"]
      env:
        - name: CHV_DISK_IMAGE
          value: {{yq .DiskImage}}
        - name: CHV_DISK_MODE
          value: {{yq .DiskModeOrDerived}}
{{- if .DiskSizeMB}}
        # The VM container sizes its own overlay to this before booting,
        # creating it that large or growing one an earlier boot of this
        # same container left behind. Omitted entirely when unset, so the
        # overlay keeps taking the disk image's own size.
        - name: CHV_DISK_SIZE_MB
          value: {{yq (itoa .DiskSizeMB)}}
{{- end}}
{{- if .Kernel}}
        - name: CHV_KERNEL
          value: {{yq .Kernel}}
{{- end}}
{{- if .Initramfs}}
        - name: CHV_INITRAMFS
          value: {{yq .Initramfs}}
{{- end}}
{{- if .Firmware}}
        - name: CHV_FIRMWARE
          value: {{yq .Firmware}}
{{- end}}
{{- if .Cmdline}}
        - name: CHV_CMDLINE
          value: {{yq .Cmdline}}
{{- end}}
{{- template "netshimEnv" .}}
        - name: CHV_CPUS
          value: {{yq (itoa .CPUs)}}
        - name: CHV_MEMORY_MB
          value: {{yq (itoa .MemoryMB)}}
{{- if .CPUsMax}}
        - name: CHV_CPUS_MAX
          value: {{yq (itoa .CPUsMax)}}
{{- end}}
{{- if .MemoryMaxMB}}
        - name: CHV_MEMORY_MAX_MB
          value: {{yq (itoa .MemoryMaxMB)}}
{{- end}}
        - name: CHV_SHUTDOWN_TIMEOUT
          value: {{yq .ShutdownTimeout}}
{{- if .GuestUser}}
        # The account "kontur exec" runs commands as inside the guest
        # (see VMSpec.GuestUser). Nothing has to tell the container how
        # to reach the guest any more: "kontur exec" goes over the VM's
        # own vsock device, whose host end is a socket in this container
        # at a path both halves of the kontur binary default to.
        - name: KONTUR_EXEC_USER
          value: {{yq .GuestUser}}
{{- end}}
      # Without this the pod's Ready condition reports on the container,
      # which is up as soon as cloud-hypervisor is exec'd -- well before
      # the guest inside it has booted -- so "kubectl wait
      # --for=condition=Ready" returns on a VM nothing can be run in yet,
      # and every caller writes a poll loop of its own instead. "kontur
      # ready" is a mode of the same binary already in this image (see
      # cmd/kontur): it dials the guest's own agent over the VM's vsock
      # device and exits zero once the guest runs a command, so the pod
      # becomes Ready when the guest does.
      #
      # "-timeout 0" makes it a single attempt -- the kubelet is already
      # retrying on periodSeconds, and a probe that waited as well would
      # only be racing it. The path is absolute because a probe is
      # resolved against whatever PATH the runtime defaults to for an
      # image that sets none, and a probe that cannot be found is a pod
      # that is never Ready.
      readinessProbe:
        exec:
          command: ["/usr/local/bin/kontur", "ready", "-timeout", "0"]
        periodSeconds: 5
        timeoutSeconds: 5
      securityContext:
        privileged: true
      volumeMounts:
        - name: images
          mountPath: /images
          readOnly: true
        - name: kvm
          mountPath: /dev/kvm
  volumes:
    - name: images
      hostPath:
        path: {{yq .ImagesHostPath}}
        type: Directory
    - name: kvm
      hostPath:
        path: /dev/kvm
        type: CharDevice
`
